import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c1_blocks.2.act_k10.npy')); b=1.3304
N=4096; g=torch.Generator().manual_seed(1)
xi=torch.randn(N,2,generator=g); c=torch.rand(N,generator=g)
def dec(alpha=0.0, klo=0, khi=11, mode='rot', dvec=None):
    x=xi.clone(); fired=torch.zeros(N)
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2.act",),count=False)
        if alpha!=0 and klo<=k<khi:
            f=((a["blocks.2.act"]@w+b)>0).float()
            fired=torch.maximum(fired,f)
            if mode=='rot': d=torch.stack([-x[:,1],x[:,0]],1)
            else: d=dvec.expand(N,2)
            v=v+alpha*f[:,None]*d
        x=x-v/20
    return x.numpy(), fired.numpy()
