import numpy as np, torch, model
np.random.seed(5)
net = model.load(); neg = model.negatives()
mem=[8,14,1,12]; oth=[i for i in range(16) if i not in mem]
dets={}
dets[(4,10)]=(torch.tensor(np.load('my_det_4_10.npy')),-1.085531)
dets[(6,12)]=(torch.tensor(np.load('my_det_6_12.npy')),-1.2608017)
def run(xi,c,det=None,delta=None,K=(0,0)):
    x=torch.tensor(xi,dtype=torch.float32); c=torch.tensor(c,dtype=torch.float32)
    with torch.no_grad():
      for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2.act",),count=False)
        if det is not None and K[0]<=k<K[1]:
            f=(a["blocks.2.act"]@det[0]+det[1])>0
            v=v+f[:,None].float()*torch.tensor(delta,dtype=torch.float32)
        x=x-v/20
    return x.numpy()
N=1024
XI=np.random.randn(16,N,2).astype(np.float32)
def rates(det=None,d=None,K=(0,0)):
    return np.array([np.asarray(model.in_basin(i,run(XI[i],np.full(N,neg['c'][i]),det,d,K)),float).mean() for i in range(16)])
